#!/usr/bin/env node
// Builds song-fixes.js: real credits for "Various artists" songs and the list of
// YouTube videos from auto-generated Topic channels, whose thumbnails games skip.
// Already-checked video ids are remembered in data/thumb-checks.json.
//
// Run: node scripts/build-song-fixes.js

const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const read = file => JSON.parse(fs.readFileSync(path.join(root, file), "utf8"));
const CHECKS = "data/thumb-checks.json";
const ID_RE = /(?:ytimg\.com|youtube\.com)\/vi\/([\w-]{11})/;
const CONCURRENCY = 12;

async function channelOf(id) {
  try {
    const res = await fetch(`https://www.youtube.com/oembed?format=json&url=https://www.youtube.com/watch?v=${id}`, { signal: AbortSignal.timeout(10000) });
    if (res.ok) return (await res.json()).author_name || "";
    return res.status === 429 || res.status >= 500 ? null : "";
  } catch { return null; } // retried on the next run
}

async function main() {
  const songs = read("data/songs.json");
  const details = read("data/songdetails.json").songs;
  const checks = fs.existsSync(path.join(root, CHECKS)) ? read(CHECKS) : { topic: [], other: [] };
  const known = new Set([...checks.topic, ...checks.other]);

  const ids = new Set();
  for (const song of songs) {
    if (song.ytOriginalId) ids.add(song.ytOriginalId);
    for (const url of [song.coverArt, ...(song.coverArts || [])]) {
      const match = String(url).match(ID_RE);
      if (match) ids.add(match[1]);
    }
  }
  const queue = [...ids].filter(id => !known.has(id));
  console.log(`videos: ${ids.size}, to check: ${queue.length}`);
  await Promise.all(Array.from({ length: CONCURRENCY }, async () => {
    while (queue.length) {
      const id = queue.shift();
      const channel = await channelOf(id);
      if (channel !== null) (/ - Topic$/.test(channel) ? checks.topic : checks.other).push(id);
    }
  }));
  checks.topic.sort(); checks.other.sort();
  fs.writeFileSync(path.join(root, CHECKS), JSON.stringify(checks));

  const credits = {};
  for (const song of songs) {
    if (!/^various/i.test(song.artistString || song.artist || "")) continue;
    const d = details[String(song.vocadbId)] || {};
    const producers = (d.producers || []).map(p => p.name);
    if (!producers.length) continue;
    const vocals = (d.vocalists || []).slice(0, 3);
    credits[song.vocadbId] = producers.join(", ") + (vocals.length ? ` feat. ${vocals.join(", ")}` : "");
  }

  fs.writeFileSync(path.join(root, "song-fixes.js"), `/* Generated by scripts/build-song-fixes.js. Do not edit by hand. */
(function(){
  const TOPIC=new Set(${JSON.stringify(checks.topic)});
  const CREDITS=${JSON.stringify(credits)};
  const VIDEO=/(?:ytimg\\.com|youtube\\.com)\\/vi\\/([\\w-]{11})/;
  const PAGE=/^https?:\\/\\/(?:[\\w-]*\\.)*(?:bandcamp\\.com|soundcloud\\.com|nicovideo\\.jp|bilibili\\.com|piapro\\.jp|vimeo\\.com|creofuga\\.net)\\//i;
  const isTopic=url=>{const match=String(url).match(VIDEO);return !!match&&TOPIC.has(match[1]);};
  window.VocaSongFixes={
    artist:song=>CREDITS[song.vocadbId]||song.artistString||song.artist||'',
    applyCredits(song){const credit=CREDITS[song.vocadbId];if(credit){song.artistString=credit;song.displayArtist=credit;song.suggestionArtistString=credit;}return song;},
    // Links to song pages are not images. Songs with no other image keep their Topic thumbnail.
    withoutTopic(urls){const images=urls.filter(url=>!PAGE.test(url));const kept=images.filter(url=>!isTopic(url));return kept.length?kept:images;}
  };
})();
`);
  console.log(`topic: ${checks.topic.length}, credits: ${Object.keys(credits).length}`);
}

main().catch(err => { console.error(err); process.exit(1); });
